import mathr = int(input('Παρακαλῶ δῶστε μου ἕναν ἀριθμό: '))while r < 1:    r = int(input('Ὀ ἀριθμὸς ποὺ δώσατε δὲν εἶναι θετικός! \n'+'Παρακαλώ δώστε θετικό αριθμό: '))if r>4 and r%2 == 1 :    i=3    c= math.ceil(math.sqrt(r))    while r%i!=0 and i <= c:        i=i+2    isprime = i > celif r !=2 and r%2 == 0:    isprime = Falseelse:    isprime = Trueprint(isprime)